"""All rounding of money lives here.

Everything is computed with exact integer/fraction arithmetic, so no result
depends on the decimal context.
"""

from __future__ import annotations

import math
from decimal import Decimal
from fractions import Fraction

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _check(value, step, method) -> None:
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method: {method!r}")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be positive")
    if not value.is_finite():
        raise ValueError("value must be finite")


def _multiple(q: Fraction, method: str) -> int:
    """The integer nearest to the non-negative fraction `q`, by `method`."""
    whole = q.numerator // q.denominator
    rest = q - whole
    if method == DOWN:
        return whole
    half = Fraction(1, 2)
    if rest > half or (rest == half and (method == HALF_UP or whole % 2 == 1)):
        return whole + 1
    return whole


def _build(negative: bool, n: int, exponent: int) -> Decimal:
    return Decimal((1 if negative else 0, tuple(int(d) for d in str(n)), exponent))


def _round(frac: Fraction, negative: bool, step: Decimal, method: str) -> Decimal:
    sign, digits, exponent = step.as_tuple()
    coefficient = int("".join(map(str, digits)))
    n = _multiple(abs(frac) / (Fraction(step)), method)
    return _build(negative, n * coefficient, exponent)


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    _check(value, step, method)
    return _round(Fraction(value), value.is_signed(), step, method)


def _add(a: Decimal, b: Decimal) -> Decimal:
    """Exact sum, at the finer exponent of the two."""
    ea, eb = a.as_tuple().exponent, b.as_tuple().exponent
    e = min(ea, eb)
    total = int(a.scaleb(0).as_integer_ratio()[0] * 0) if False else 0
    ia = Fraction(a) / Fraction(10) ** e
    ib = Fraction(b) / Fraction(10) ** e
    total = int(ia + ib)
    negative = total < 0 or (total == 0 and a.is_signed() and b.is_signed())
    return _build(negative, abs(total), e)


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    if not isinstance(step, Decimal):
        raise TypeError("step must be Decimal")
    amounts = list(amounts)
    for a in amounts:
        _check(a, step, HALF_UP)
    _check(Decimal(0), step, HALF_UP)
    parts = [round_amount(a, step, DOWN) for a in amounts]
    exact = sum((Fraction(a) for a in amounts), Fraction(0))
    whole = _round(exact, exact < 0, step, HALF_UP)
    zero = _build(False, 0, step.as_tuple().exponent)
    got = zero
    for p in parts:
        got = _add(got, p)
    rest = _add(whole, got.copy_negate())
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            parts[i] = _add(parts[i], rest)
            break
    return parts


def legacy_cents(value: float, places: int = 2) -> float:
    if not isinstance(places, int) or isinstance(places, bool) or not 0 <= places <= 6:
        raise ValueError("places must be an integer from 0 to 6")
    factor = 10**places
    return math.floor(value * factor + 0.5) / factor


def fixed(value: float | Decimal, places: int, method: str = HALF_EVEN) -> str:
    if not isinstance(places, int) or isinstance(places, bool):
        raise TypeError("places must be an int")
    if places < 0:
        raise ValueError("places must not be negative")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method: {method!r}")
    if isinstance(value, float):
        if method != HALF_EVEN:
            raise ValueError("a float can only be written half-even")
        return format(value, f".{places}f")
    if not isinstance(value, Decimal):
        raise TypeError("value must be a float or a Decimal")
    r = round_amount(value, Decimal((0, (1,), -places)), method)
    sign, digits, _ = r.as_tuple()
    text = "".join(map(str, digits)).rjust(places + 1, "0")
    if places:
        text = text[:-places] + "." + text[-places:]
    return ("-" if sign else "") + text
