    """Exact sum, at the finer exponent of the two (zero sign as Decimal does)."""
    e = min(a.as_tuple().exponent, b.as_tuple().exponent)
    total = (Fraction(a) + Fraction(b)) / Fraction(10) ** e
    n = int(total)
    negative = n < 0 or (n == 0 and a.is_signed() and b.is_signed())
    return _build(negative, abs(n), e)


